svg.script:

//!export-start
var _pn_conveyorSpeed = 0.0;
var _pn_setConveyorSpeed = 0.0;

var _pn_lacquerLevel = 50.0;

var _pn_lacquerTemp = 22.5;
var _pn_setLacquerTemp = 22.5;

var _pn_pumpSpeed = 0.0;
var _pn_setPumpSpeed = 0.0;

var _pn_bladesOpening = 0.0;
var _pn_setBladesOpening = 0.0;

var _pn_viscosity = 0.0;
var _pn_setViscosity = 0.0;

var _pn_sensorOperator = 0;
var _pn_sensorC1 = 0;
var _pn_sensorC2 = 0;

var _pn_dosingLacquer = 0;
var _pn_dosingSolvent = 0;
var _pn_viscosityStatus = 0;
//!export-end

function postValue(id, value) { console.error('Not defined!'); }

function putValue(id, value) {
  var v = Number(value);
  switch(id) {
    case '_pn_conveyorSpeed':
      document.getElementById('val_conveyor_speed').textContent = v.toFixed(1) + ' m/min';
      break;
    case '_pn_setConveyorSpeed':
      _pn_setConveyorSpeed = v;
      document.getElementById('set_conveyor_speed').textContent = 'SP: ' + v.toFixed(1);
      break;
    case '_pn_lacquerLevel':
      var clamp = Math.max(0, Math.min(100, v));
      var h = (clamp / 100) * 85;
      var y = 565 - h;
      var rect = document.getElementById('lacquer_level');
      rect.setAttribute('height', h);
      rect.setAttribute('y', y);
      break;
    case '_pn_lacquerTemp':
      document.getElementById('val_lacquer_temp').textContent = v.toFixed(1) + ' °C';
      break;
    case '_pn_setLacquerTemp':
      _pn_setLacquerTemp = v;
      document.getElementById('set_lacquer_temp').textContent = 'SP: ' + v.toFixed(1);
      break;
    case '_pn_pumpSpeed':
      _pn_pumpSpeed = v;
      document.getElementById('val_pump_speed').textContent = v.toFixed(0) + ' RPM';
      break;
    case '_pn_setPumpSpeed':
      _pn_setPumpSpeed = v;
      document.getElementById('set_pump_speed').textContent = 'SP: ' + v.toFixed(0);
      break;
    case '_pn_bladesOpening':
      document.getElementById('val_blades_opening').textContent = v.toFixed(1) + ' nm';
      break;
    case '_pn_setBladesOpening':
      _pn_setBladesOpening = v;
      document.getElementById('set_blades_opening').textContent = 'SP: ' + v.toFixed(1);
      break;
    case '_pn_viscosity':
      document.getElementById('val_viscosity').textContent = v.toFixed(1) + ' cP';
      break;
    case '_pn_setViscosity':
      _pn_setViscosity = v;
      document.getElementById('set_viscosity').textContent = 'SP: ' + v.toFixed(1);
      break;
    case '_pn_sensorOperator':
      document.getElementById('sensor_operator_light').style.fill = (v !== 0) ? '#22c55e' : '#475569';
      break;
    case '_pn_sensorC1':
      document.getElementById('sensor_c1_intake_light').style.fill = (v !== 0) ? '#22c55e' : '#475569';
      break;
    case '_pn_sensorC2':
      document.getElementById('sensor_c2_middle_light').style.fill = (v !== 0) ? '#22c55e' : '#475569';
      break;
    case '_pn_viscosityStatus':
      document.getElementById('light_viscosity_status').style.fill = (v !== 0) ? '#3b82f6' : '#475569';
      break;
    case '_pn_dosingLacquer':
      var dl = document.getElementById('light_dosing_lacquer');
      v !== 0 ? dl.classList.add('dosing-lacquer-active') : dl.classList.remove('dosing-lacquer-active');
      break;
    case '_pn_dosingSolvent':
      var ds = document.getElementById('light_dosing_solvent');
      v !== 0 ? ds.classList.add('dosing-lacquer-active') : ds.classList.remove('dosing-lacquer-active'); // fallback fix
      break;
  }
}

// Click bindings to trigger Setpoint writes back to FUXA via postValue
document.getElementById('bg_conveyor_speed').addEventListener('click', function() {
  var newVal = prompt('Enter Setpoint for Conveyor Speed (m/min):', _pn_setConveyorSpeed);
  if (newVal !== null &amp;&amp; !isNaN(newVal)) { postValue('_pn_setConveyorSpeed', Number(newVal)); }
});

document.getElementById('bg_lacquer_temp').addEventListener('click', function() {
  var newVal = prompt('Enter Setpoint for Lacquer Temperature (°C):', _pn_setLacquerTemp);
  if (newVal !== null &amp;&amp; !isNaN(newVal)) { postValue('_pn_setLacquerTemp', Number(newVal)); }
});

document.getElementById('bg_main_pump_speed').addEventListener('click', function() {
  var newVal = prompt('Enter Setpoint for Main Pump Speed (RPM):', _pn_setPumpSpeed);
  if (newVal !== null &amp;&amp; !isNaN(newVal)) { postValue('_pn_setPumpSpeed', Number(newVal)); }
});

document.getElementById('bg_blades_opening').addEventListener('click', function() {
  var newVal = prompt('Enter Setpoint for Blades Opening (nm):', _pn_setBladesOpening);
  if (newVal !== null &amp;&amp; !isNaN(newVal)) { postValue('_pn_setBladesOpening', Number(newVal)); }
});

document.getElementById('bg_viscosity').addEventListener('click', function() {
  var newVal = prompt('Enter Setpoint for Viscosity (cP):', _pn_setViscosity);
  if (newVal !== null &amp;&amp; !isNaN(newVal)) { postValue('_pn_setViscosity', Number(newVal)); }
});

var pumpRot = 0;
var animFrame;
var flowLines = document.getElementById('animated_flow_lines');
var pumpAnim = document.getElementById('pump_main_anim');

function animate() {
  if (_pn_pumpSpeed !== 0) {
    pumpRot = (pumpRot + (_pn_pumpSpeed * 0.05)) % 360;
    pumpAnim.setAttribute('transform', 'rotate(' + pumpRot + ' 755 630)');
    flowLines.style.opacity = '1';
  } else {
    flowLines.style.opacity = '0';
  }
  animFrame = requestAnimationFrame(animate);
}
animFrame = requestAnimationFrame(animate);

var observer = new MutationObserver(function(mutations) {
  mutations.forEach(function(mutation) {
    mutation.removedNodes.forEach(function(node) {
      if (node.id === 'curtain_coater_hmi') {
        cancelAnimationFrame(animFrame);
        observer.disconnect();
      }
    });
  });
});
observer.observe(document.body, { childList: true, subtree: true });
